using System;
using System.Net;
using System.Net.Sockets;
using System.Threading.Tasks;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Stationeers has no Steam server query (A2S): it lists itself on its own master server and players connect over
// RakNet on the game port. RakNet answers an "unconnected ping" (offline message, no connection, nothing written to
// the game console) with an "unconnected pong", so the status check sends one to the game port and waits for the
// answer. The game does not publish its player count outside a connection, so the players are not reported.
string address = Convert.ToString(Dynamic.Address);
if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
int port = ThisService.GamePort; // the panel's query port is not used by the game

// RakNet's offline-message id.
byte[] magic = { 0x00, 0xFF, 0xFF, 0x00, 0xFE, 0xFE, 0xFE, 0xFE, 0xFD, 0xFD, 0xFD, 0xFD, 0x12, 0x34, 0x56, 0x78 };
try
{
    if (!IPAddress.TryParse(address, out var ip)) ip = (await Dns.GetHostAddressesAsync(address))[0];
    var ping = new byte[1 + 8 + 16 + 8];
    ping[0] = 0x01; // ID_UNCONNECTED_PING
    var ticks = BitConverter.GetBytes((long)Environment.TickCount64);
    if (BitConverter.IsLittleEndian) Array.Reverse(ticks);
    Buffer.BlockCopy(ticks, 0, ping, 1, 8);
    Buffer.BlockCopy(magic, 0, ping, 9, 16);
    var guid = BitConverter.GetBytes((long)Random.Shared.NextInt64());
    Buffer.BlockCopy(guid, 0, ping, 25, 8);

    using (var udp = new UdpClient(ip.AddressFamily))
    {
        udp.Connect(ip, port);
        string error = "No answer from " + address + ":" + port + " (UDP).";
        for (var attempt = 0; attempt < 2; attempt++)
        {
            await udp.SendAsync(ping, ping.Length);
            var receive = udp.ReceiveAsync();
            if (await Task.WhenAny(receive, Task.Delay(1500)) != receive) continue;
            var reply = receive.Result.Buffer;
            // ID_UNCONNECTED_PONG: 0x1C, time (8), server guid (8), magic (16), optional data.
            if (reply.Length >= 33 && reply[0] == 0x1C)
            {
                Globals.ReturnValue = new GameQueryResponse
                {
                    Success = true,
                    Status = "online",
                    Protocol = "custom_script",
                    Address = address,
                    Hostname = $"{address}:{port}",
                    Name = ThisService.Name,
                    GameType = "Stationeers",
                    Map = "",
                    NumPlayers = 0,
                    MaxPlayers = ThisService.Slots,
                    NumSpectators = 0,
                    MaxSpectators = 0,
                    Retries = attempt
                };
                return;
            }
            error = "Unexpected answer from " + address + ":" + port + " (UDP).";
        }
        Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", error);
    }
}
catch (Exception ex)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
}

//refAssemblies: TCAdmin.Monitor.SDK.dll, System.Diagnostics.Process.dll, System.Net.Primitives.dll, System.Net.Sockets.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Graceful stop. "quit" ends the server at once WITHOUT saving, and a signal does the same, so the world is saved
// first: the "save" console command (sent through the same path as a command typed in the console), then the script
// waits until a newer .save file exists under saves/, then sends "quit" and waits for the server to exit. The server
// hosts its game port (RakNet) only once the world is loaded: when the port does not answer a RakNet ping, there is
// no world to save (and the console reads no commands yet), so the script returns and the panel stops the process.
const int saveWaitSeconds = 120;
const int exitWaitSeconds = 60;
var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
var binary = System.OperatingSystem.IsWindows() ? "rocketstation_DedicatedServer.exe" : "rocketstation_DedicatedServer.x86_64";
var saves = Path.Combine(root, "saves");

List<int> ServerPids()
{
    var pids = new List<int>();
    if (System.OperatingSystem.IsWindows())
    {
        foreach (var p in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(binary)))
        {
            try { if (p.MainModule.FileName.StartsWith(root, StringComparison.OrdinalIgnoreCase)) pids.Add(p.Id); }
            catch { } // exited meanwhile
        }
        return pids;
    }
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var exe = new FileInfo(Path.Combine(dir, "exe")).LinkTarget ?? "";
            if (exe.StartsWith(root, StringComparison.Ordinal) && Path.GetFileName(exe) == binary) pids.Add(pid);
        }
        catch { } // processes of other users, or gone meanwhile
    }
    return pids;
}

// Newest .save file under saves/ (a few levels deep). Never follows links: the script runs as the monitor.
DateTime NewestSave()
{
    var newest = DateTime.MinValue;
    try
    {
        var di = new DirectoryInfo(saves);
        if (!di.Exists || di.LinkTarget != null) return newest;
        var walk = new EnumerationOptions { RecurseSubdirectories = true, MaxRecursionDepth = 3, AttributesToSkip = FileAttributes.ReparsePoint, IgnoreInaccessible = true };
        foreach (var f in di.EnumerateFiles("*.save", walk))
            if (f.LastWriteTimeUtc > newest) newest = f.LastWriteTimeUtc;
    }
    catch { } // saves folder changing meanwhile
    return newest;
}

// RakNet "unconnected ping" (offline message, nothing logged): true when the game port answers.
async Task<bool> WorldLoaded()
{
    try
    {
        var ip = IPAddress.Parse(ThisService.IPAddress);
        byte[] magic = { 0x00, 0xFF, 0xFF, 0x00, 0xFE, 0xFE, 0xFE, 0xFE, 0xFD, 0xFD, 0xFD, 0xFD, 0x12, 0x34, 0x56, 0x78 };
        var ping = new byte[33];
        ping[0] = 0x01;
        Buffer.BlockCopy(magic, 0, ping, 9, 16);
        using (var udp = new UdpClient(ip.AddressFamily))
        {
            udp.Connect(ip, ThisService.GamePort);
            for (var attempt = 0; attempt < 3; attempt++)
            {
                await udp.SendAsync(ping, ping.Length);
                var receive = udp.ReceiveAsync();
                if (await Task.WhenAny(receive, Task.Delay(1000)) == receive && receive.Result.Buffer.Length > 0 && receive.Result.Buffer[0] == 0x1C) return true;
            }
        }
    }
    catch { } // port closed (ICMP unreachable) or no address
    return false;
}

if (ServerPids().Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    return;
}
if (!await WorldLoaded())
{
    // The console reads no commands before the world is loaded either, so the panel stops the process.
    ScriptConsole.WriteLine((object)"The world is not loaded yet (the game port does not answer): nothing to save, the panel stops the server.");
    return;
}
var before = NewestSave();
await ServiceManagerService.SendConsoleInput(ThisService.ServiceId, "save");
ScriptConsole.WriteLine((object)"Asked the server to save the world (save).");
var saved = false;
for (var second = 1; second <= saveWaitSeconds && !saved; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (ServerPids().Count == 0)
    {
        ScriptConsole.WriteLine((object)"The server exited while saving.");
        return;
    }
    if (NewestSave() > before)
    {
        // The file appears when the zip is written; give the server a moment to finish it.
        await Task.Delay(3000, ThisCancellationToken);
        saved = true;
        ScriptConsole.WriteLine((object)("The world was saved after " + second + " s."));
    }
}
if (!saved) ScriptConsole.WriteLine((object)("No new save within " + saveWaitSeconds + " s; quitting anyway."));
await ServiceManagerService.SendConsoleInput(ThisService.ServiceId, "quit");
ScriptConsole.WriteLine((object)"Asked the server to quit (quit).");
for (var second = 1; second <= exitWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (ServerPids().Count == 0)
    {
        ScriptConsole.WriteLine((object)("The server exited after " + second + " s."));
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not exit within " + exitWaitSeconds + " s; the panel stops it now."));

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Stationeers servers load every mod folder under mods/ that has an About/About.xml (it adds new ones to
// modconfig.xml, enabled) when they start. A dedicated server cannot download Workshop items itself, so this copies
// the downloaded item to mods/workshop-<id>; the server loads it at its next start.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string installPath = Convert.ToString(Dynamic.InstallPath);
string root = (string)ThisService.RootDirectory;

if (string.IsNullOrEmpty(installPath) || !Directory.Exists(installPath) || IsLink(installPath))
    throw new Exception("Nothing was downloaded for Workshop item " + fileId + ".");
// The script runs as the monitor: never follow a link the service user could have planted in the download.
var walk = new EnumerationOptions { RecurseSubdirectories = true, AttributesToSkip = FileAttributes.ReparsePoint, IgnoreInaccessible = true };
string mods = ModsDir(root);
string target = Path.Combine(mods, "workshop-" + fileId);
// The download tool keeps its own state in .DepotDownloader; it is not part of the mod.
// Linux: the game skips <mod>/GameData/Language only when the path contains "gamedata\language" (a Windows
// separator), so on Linux it parses the language files as game data, fails ("Failed to Deserialize GameData") and
// never finishes loading the world. The Linux copy leaves the mod's translations out; the server does not need them.
bool LinuxLanguage(string path)
{
    if (System.OperatingSystem.IsWindows()) return false;
    var parts = Path.GetRelativePath(installPath, path).Split(Path.DirectorySeparatorChar);
    return parts.Length >= 2 && string.Equals(parts[0], "GameData", StringComparison.OrdinalIgnoreCase) && string.Equals(parts[1], "Language", StringComparison.OrdinalIgnoreCase);
}
int skippedLanguage = 0;
bool Skip(string path)
{
    if (IsLink(path) || Path.GetRelativePath(installPath, path).Split(Path.DirectorySeparatorChar)[0] == ".DepotDownloader") return true;
    if (!LinuxLanguage(path)) return false;
    if (File.Exists(path)) skippedLanguage++;
    return true;
}
// The game reads <mod>/About/About.xml and <mod>/GameData by exact name; Linux file names are case-sensitive and some
// mods ship "Gamedata" or "about" (Windows hides that), so the copy uses the game's spelling for those two folders.
string Target(string path)
{
    var parts = Path.GetRelativePath(installPath, path).Split(Path.DirectorySeparatorChar);
    foreach (var known in new[] { "About", "GameData" })
        if (string.Equals(parts[0], known, StringComparison.OrdinalIgnoreCase)) parts[0] = known;
    return Path.Combine(target, Path.Combine(parts));
}
if (!Directory.EnumerateFiles(installPath, "*", walk).Any(f => !Skip(f) && string.Equals(Path.GetFileName(f), "About.xml", StringComparison.OrdinalIgnoreCase)
        && string.Equals(Path.GetFileName(Path.GetDirectoryName(f)), "About", StringComparison.OrdinalIgnoreCase)))
    throw new Exception("Workshop item " + fileId + " is not a mod (no About/About.xml). Worlds, IC10 scripts and mods that need a mod loader cannot be installed this way.");

RemoveModFolder(mods, fileId);
Directory.CreateDirectory(target);
int files = 0;
void Own(string path) { if (!System.OperatingSystem.IsWindows()) Globals.OperatingSystem.SetFileOwnerAutoDetect(path); }
Own(target);
foreach (var dir in Directory.EnumerateDirectories(installPath, "*", walk).Where(d => !Skip(d)))
{
    var copy = Target(dir);
    Directory.CreateDirectory(copy);
    Own(copy);
}
foreach (var file in Directory.EnumerateFiles(installPath, "*", walk).Where(f => !Skip(f)))
{
    var copy = Target(file);
    File.Copy(file, copy, true);
    Own(copy);
    files++;
}
ScriptConsole.WriteLine((object)("Copied Workshop item " + fileId + " (" + files + " files) to mods/workshop-" + fileId + "."));
if (skippedLanguage > 0)
    ScriptConsole.WriteLine((object)("Left out " + skippedLanguage + " translation files (GameData/Language): the Linux server fails to load mods that have them. Item names fall back to the mod's own names."));
if (Directory.EnumerateFiles(target, "*.dll", walk).Any())
    ScriptConsole.WriteLine((object)"Warning: this mod contains code (.dll). Code mods need a mod loader (BepInEx / StationeersLaunchPad), which a vanilla server does not have: only its GameData (XML) part is loaded.");
ScriptConsole.WriteLine((object)"The server loads the mod the next time it starts. Players need the same mod (subscribe to it on the Workshop).");

// A symbolic link or junction (reparse point on Windows).
bool IsLink(string path)
{
    // LinkTarget also sees a dangling link (File.Exists is false for one) and Windows junctions.
    var info = new FileInfo(path);
    if (info.LinkTarget != null) return true;
    if (!info.Exists && !Directory.Exists(path)) return false;
    return (File.GetAttributes(path) & FileAttributes.ReparsePoint) != 0;
}

// <root>/mods, created when missing. The script runs as the monitor, so the folder must be a real folder inside the
// service root: a link planted by the service user would make the monitor write or delete files elsewhere.
string ModsDir(string serviceRoot)
{
    if (IsLink(serviceRoot)) throw new Exception("The service folder is a link; refusing to change mods.");
    string dir = Path.Combine(serviceRoot, "mods");
    if (!Directory.Exists(dir) && File.Exists(dir)) throw new Exception("mods is a file, not a folder.");
    if (!Directory.Exists(dir))
    {
        Directory.CreateDirectory(dir);
        if (!System.OperatingSystem.IsWindows()) Globals.OperatingSystem.SetFileOwnerAutoDetect(dir);
    }
    if (IsLink(dir)) throw new Exception("The mods folder is a link; refusing to change it. Delete the link and try again.");
    return dir;
}

// Deletes mods/workshop-<id> without following links: a link inside it is removed, never its target.
bool RemoveModFolder(string modsDir, string id)
{
    string dir = Path.Combine(modsDir, "workshop-" + id);
    if (IsLink(dir)) { File.Delete(dir); return true; }
    if (!Directory.Exists(dir)) return false;
    DeleteTree(dir);
    return true;
}

void DeleteTree(string dir)
{
    foreach (var entry in Directory.EnumerateFileSystemEntries(dir).ToList())
    {
        if (IsLink(entry))
        {
            if (Directory.Exists(entry)) Directory.Delete(entry, false); else File.Delete(entry);
        }
        else if (Directory.Exists(entry)) DeleteTree(entry);
        else
        {
            File.SetAttributes(entry, FileAttributes.Normal);
            File.Delete(entry);
        }
    }
    Directory.Delete(dir, false);
}

