// Deletes mods/workshop-<id>; from its next start the server no longer loads the mod (it drops the missing folder
// from modconfig.xml itself). Never follows links.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string root = (string)ThisService.RootDirectory;

string mods = ModsDir(root);
bool removed;
try { removed = RemoveModFolder(mods, fileId); }
catch (Exception ex) when (ex is IOException || ex is UnauthorizedAccessException)
{
    throw new Exception("The running server uses the files of mods/workshop-" + fileId + ": stop the server and uninstall the mod again. (" + ex.Message + ")");
}
ScriptConsole.WriteLine((object)(removed
    ? "Removed Workshop item " + fileId + " from the mods folder. The server no longer loads it after its next start."
    : "Workshop item " + fileId + " was not in the mods folder."));

